    public boolean withinClerkLimit(BigDecimal due, String grade, LocalDate today) {
        BigDecimal clerkLimit = clerkLimitFor(grade, today);
        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
    }
